fn fibonacci(n: usize) -> Vec<i32> {
    // We assume n >= 2 and that F(n) < 2^31, so all Fibonacci numbers up to F(n-1)
    // fit in i32 without overflow.
    let mut result: Vec<i32> = Vec::with_capacity(n);
    
    // Base cases
    result.push(0); // F(0)
    result.push(1); // F(1)
    
    // Compute subsequent Fibonacci numbers iteratively
    for i in 2..n {
        // Since F(i-1) and F(i-2) are guaranteed to fit in i32,
        // their sum also fits in i32 under the problem assumption.
        let next = result[i - 1] + result[i - 2];
        result.push(next);
    }
    
    result
}

